import{_ as o,I as e,o as h,c,b6 as i,j as a,J as l,w as t,a as n}from"./chunks/framework.BUXTSoD9.js";const P=JSON.parse('{"title":"온라인 시험 및 관리 시스템 개발 실전","description":"","frontmatter":{},"headers":[],"relativePath":"ko-kr/stage-2/assignments/exam-management-express/index.md","filePath":"ko-kr/stage-2/assignments/exam-management-express/index.md"}'),b={name:"ko-kr/stage-2/assignments/exam-management-express/index.md"},u={style:{margin:"32px 0"}};function k(g,s,m,x,f,_){const p=e("StepBar"),d=e("ClientOnly"),r=e("el-card");return h(),c("div",null,[s[2]||(s[2]=i('<h1 id="온라인-시험-및-관리-시스템-개발-실전" tabindex="-1">온라인 시험 및 관리 시스템 개발 실전 <a class="header-anchor" href="#온라인-시험-및-관리-시스템-개발-실전" aria-label="Permalink to “온라인 시험 및 관리 시스템 개발 실전”">​</a></h1><h2 id="개요" tabindex="-1">개요 <a class="header-anchor" href="#개요" aria-label="Permalink to “개요”">​</a></h2><p>본 실전 프로젝트는 실제 PRD를 바탕으로, 온라인 시험 및 관리 시스템을 처음부터 완성하는 것을 요구합니다. 이 프로젝트의 특별한 점은 여러 역할(학생과 관리자)이 포함되어 있으며, 각 역할이 보는 페이지와 수행할 수 있는 조작이 다르다는 것입니다. Express를 사용하여 백엔드를 구축하고, 완전한 시험 비즈니스 체인을 구현합니다.</p><p>이것은 Stage 2의 종합 실전环节입니다. 다중 역할 권한 시스템은 실제 업무에서 매우 흔하며, 이 패턴을 마스터하면 교육, SaaS, 백엔드 관리 등 다양한 비즈니스 시나리오에 대응할 수 있습니다.</p><h2 id="사전-지식" tabindex="-1">사전 지식 <a class="header-anchor" href="#사전-지식" aria-label="Permalink to “사전 지식”">​</a></h2><p>본 프로젝트를 시작하기 전에 다음 내용을 이미 숙지해야 합니다:</p><ul><li>프론트엔드 페이지 디자인 및 컴포넌트 라이브러리 사용 (<a href="./../../frontend/ui-design/">UI 디자인</a>, <a href="./../../frontend/modern-component-library/">현대적 컴포넌트 라이브러리</a>)</li><li>백엔드 인터페이스 설계 및 개발 (<a href="./../../backend/ai-interface-code/">인터페이스 코드 작성</a>)</li><li>데이터베이스 기초와 Supabase (<a href="./../../backend/database-supabase/">데이터베이스에서 Supabase까지</a>)</li><li>Git 워크플로우와 배포 (<a href="./../../backend/git-workflow/">Git과 GitHub</a>, <a href="./../../backend/zeabur-deployment/">웹 애플리케이션 배포</a>)</li></ul><h2 id="학습-목표" tabindex="-1">학습 목표 <a class="header-anchor" href="#학습-목표" aria-label="Permalink to “학습 목표”">​</a></h2><p>본 실전을 완료하면 다음이 가능합니다:</p><ol><li>실제 PRD를 읽고 이해하여, 개발 과제 목록을 추출</li><li>다중 역할 시스템의 권한 제어와 페이지 라우팅 설계</li><li>Express를 사용하여 완전한 백엔드 API 구현</li><li>시험, 제출, 자동 채점의 비즈니스 체인 구현</li><li>엔드투엔드 통합 디버깅을 완료하고, 시연 가능한 비즈니스 시스템 프로토타입 납품</li></ol><h2 id="프로젝트-소개" tabindex="-1">프로젝트 소개 <a class="header-anchor" href="#프로젝트-소개" aria-label="Permalink to “프로젝트 소개”">​</a></h2><p>구축할 제품은 온라인 시험 및 관리 시스템으로, 세 가지 하위 시스템을 포함합니다:</p><table tabindex="0"><thead><tr><th>하위 시스템</th><th>담당</th></tr></thead><tbody><tr><td><strong>공식 웹사이트 프론트엔드</strong></td><td>플랫폼 소개, 로그인 입구</td></tr><tr><td><strong>학생 페이지</strong></td><td>시험 목록, 답안 작성, 제출, 성적 조회</td></tr><tr><td><strong>관리 백엔드</strong></td><td>문제 은행 관리, 시험 관리, 제출 기록, 성적 통계</td></tr></tbody></table><p>백엔드는 Express를 사용하며, 로그인 인증, 역할 권한, 시험 및 문제 은행 관리, 제출 프로세스와 자동 채점, 성적 및 통계 관리를 지원해야 합니다.</p><div class="tip custom-block"><p class="custom-block-title">PRD 입구</p><p>본 프로젝트의 요구사항 문서는 GitHub에 있습니다: <a href="https://github.com/datawhalechina/easy-vibe/blob/main/docs/zh-cn/stage-2/assignments/exam-management-express/PRD.md" target="_blank" rel="noreferrer">PRD 보기</a></p></div>',15)),a("div",u,[l(d,null,{default:t(()=>[l(p,{active:0,items:[{title:"요구사항 분석",description:"PRD를 읽고 역할, 페이지, 시험 체인 및 데이터 모델을 명확히 합니다"},{title:"골격 구축",description:"AI로 학생 페이지와 관리 페이지 골격을 생성합니다"},{title:"백엔드 개발",description:"Express로 로그인, 시험, 제출, 채점을 연결합니다"},{title:"통합 디버깅 및 출시",description:"엔드투엔드로 실행하고, 배포하여 데모를 준비합니다"}]})]),_:1})]),s[3]||(s[3]=i(`<h2 id="제1부-요구사항-분석" tabindex="-1">제1부: 요구사항 분석 <a class="header-anchor" href="#제1부-요구사항-분석" aria-label="Permalink to “제1부: 요구사항 분석”">​</a></h2><h3 id="_1-1-prd-읽기" tabindex="-1">1.1 PRD 읽기 <a class="header-anchor" href="#_1-1-prd-읽기" aria-label="Permalink to “1.1 PRD 읽기”">​</a></h3><p>PRD 문서를 열고 다음 질문에 중점적으로 답하세요:</p><ul><li>시스템에 몇 개의 역할이 있나요? 각각 무엇을 할 수 있나요?</li><li>페이지 목록이 완전한가요? 학생 페이지와 관리 페이지에 각각 어떤 페이지가 있나요?</li><li>어떤 문제 유형을 지원하나요? 각 문제 유형의 채점 로직은 무엇인가요?</li><li>시험의 완전한 프로세스는 무엇인가요? (발행 -&gt; 시작 -&gt; 답안 작성 -&gt; 제출 -&gt; 채점 -&gt; 성적 조회)</li></ul><div class="warning custom-block"><p class="custom-block-title custom-block-title-default">WARNING</p><p>위 질문에 명확한 답이 없다면, 코드 작성을 시작하지 마세요. 요구사항 이해가 불명확한 것은 재작업의 가장 흔한 원인입니다.</p></div><h3 id="_1-2-시스템-아키텍처-확인" tabindex="-1">1.2 시스템 아키텍처 확인 <a class="header-anchor" href="#_1-2-시스템-아키텍처-확인" aria-label="Permalink to “1.2 시스템 아키텍처 확인”">​</a></h3><p>PRD를 바탕으로 시스템의 전체 아키텍처를 정리합니다:</p><div class="language-mermaid"><button title="Copy Code" class="copy"></button><span class="lang">mermaid</span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">flowchart TD</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">  prd[&quot;PRD&quot;] --&gt; web[&quot;공식 웹사이트 프론트엔드&quot;]</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">  prd --&gt; student[&quot;학생 페이지&quot;]</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">  prd --&gt; admin[&quot;관리 백엔드&quot;]</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">  student --&gt; auth[&quot;인증&quot;]</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">  student --&gt; exam[&quot;시험 및 답안 작성&quot;]</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">  exam --&gt; db[&quot;데이터베이스&quot;]</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">  admin --&gt; question[&quot;문제 은행 관리&quot;]</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">  admin --&gt; submission[&quot;제출 기록 및 성적 통계&quot;]</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">  question --&gt; db</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">  submission --&gt; db</span></span></code></pre></div><h2 id="제2부-프로젝트-골격-구축" tabindex="-1">제2부: 프로젝트 골격 구축 <a class="header-anchor" href="#제2부-프로젝트-골격-구축" aria-label="Permalink to “제2부: 프로젝트 골격 구축”">​</a></h2><h3 id="_2-1-프론트엔드-페이지-생성" tabindex="-1">2.1 프론트엔드 페이지 생성 <a class="header-anchor" href="#_2-1-프론트엔드-페이지-생성" aria-label="Permalink to “2.1 프론트엔드 페이지 생성”">​</a></h3><p>프롬프트 참고:</p><div class="language-text"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>현재 PRD를 기반으로 온라인 시험 및 관리 시스템의 프론트엔드 골격을 생성해 줘.</span></span>
<span class="line"><span></span></span>
<span class="line"><span>기술 스택 요구사항:</span></span>
<span class="line"><span>- Next.js App Router</span></span>
<span class="line"><span>- TypeScript</span></span>
<span class="line"><span>- Tailwind CSS</span></span>
<span class="line"><span>- shadcn/ui</span></span>
<span class="line"><span></span></span>
<span class="line"><span>페이지 목록:</span></span>
<span class="line"><span>1. 홈페이지 /</span></span>
<span class="line"><span>2. 로그인 페이지 /login</span></span>
<span class="line"><span>3. 학생 시험 목록 페이지 /student/exams</span></span>
<span class="line"><span>4. 학생 답안 작성 페이지 /student/exams/[id]</span></span>
<span class="line"><span>5. 학생 성적 페이지 /student/history</span></span>
<span class="line"><span>6. 관리 백엔드 홈페이지 /admin</span></span>
<span class="line"><span>7. 시험 관리 페이지 /admin/exams</span></span>
<span class="line"><span>8. 문제 은행 관리 페이지 /admin/questions</span></span>
<span class="line"><span>9. 제출 기록 페이지 /admin/submissions</span></span>
<span class="line"><span></span></span>
<span class="line"><span>요구사항:</span></span>
<span class="line"><span>- 학생 페이지는 명확하고, 집중하기 쉬우며, 답안 작성이 편리해야 함</span></span>
<span class="line"><span>- 관리 페이지는 사이드바 + 상단바 레이아웃 사용</span></span>
<span class="line"><span>- 먼저 mock 데이터를 사용하고, 실제 인터페이스는 연결하지 마</span></span>
<span class="line"><span>- 데스크톱과 모바일의 기본 사용 가능성에 주의</span></span></code></pre></div><h3 id="_2-2-학생-답안-작성-페이지-완성" tabindex="-1">2.2 학생 답안 작성 페이지 완성 <a class="header-anchor" href="#_2-2-학생-답안-작성-페이지-완성" aria-label="Permalink to “2.2 학생 답안 작성 페이지 완성”">​</a></h3><p>답안 작성 페이지는 학생 페이지의 핵심 페이지이며, 중점적으로 완성합니다:</p><div class="language-text"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>학생 답안 작성 페이지를 계속 완성해 줘.</span></span>
<span class="line"><span></span></span>
<span class="line"><span>이것은 온라인 시험 시스템의 답안 작성 페이지로, 다음을 포함해야 함:</span></span>
<span class="line"><span>- 상단에 시험 제목, 카운트다운, 답안 작성 완료 문항 수 표시</span></span>
<span class="line"><span>- 중간에 문제 내용과 선택지 표시</span></span>
<span class="line"><span>- 단답형, 참/거짓, 서술형 세 가지 문제 유형 지원</span></span>
<span class="line"><span>- 왼쪽이나 상단에 답안 카드가 있어, 각 문제의 답안 작성 여부 표시</span></span>
<span class="line"><span>- 제출 전 확인 팝업 표시</span></span>
<span class="line"><span></span></span>
<span class="line"><span>먼저 mock 데이터로 상호작용을 구현하고, 실제 인터페이스는 연결하지 마.</span></span>
<span class="line"><span></span></span>
<span class="line"><span>요구사항:</span></span>
<span class="line"><span>- 인터페이스는 간결하게, 백엔드 테이블 페이지처럼 보이지 않게</span></span>
<span class="line"><span>- 카운트다운은 눈에 띄지만, 너무 큰 압박감을 주지 않게</span></span>
<span class="line"><span>- 빈 상태와 loading 상태 포함</span></span></code></pre></div><h3 id="_2-3-관리자-백엔드-완성" tabindex="-1">2.3 관리자 백엔드 완성 <a class="header-anchor" href="#_2-3-관리자-백엔드-완성" aria-label="Permalink to “2.3 관리자 백엔드 완성”">​</a></h3><p>관리자 백엔드 첫 번째 버전은 세 가지 핵심 영역에 집중합니다:</p><ul><li><strong>시험 관리</strong>: 시험 생성, 시간 설정, 발행 상태</li><li><strong>문제 은행 관리</strong>: 문제 추가, 문제 편집, 문제 유형별 필터링</li><li><strong>제출 기록</strong>: 학생 제출, 점수, 시간 확인</li></ul><h3 id="_2-4-페이지-구조-검증" tabindex="-1">2.4 페이지 구조 검증 <a class="header-anchor" href="#_2-4-페이지-구조-검증" aria-label="Permalink to “2.4 페이지 구조 검증”">​</a></h3><p>항목별로 확인:</p><ul><li>[ ] 학생 페이지와 관리 페이지의 진입점이 분리되어 있는지</li><li>[ ] 로그인 페이지, 시험 목록, 답안 작성 페이지, 성적 페이지가 완전한지</li><li>[ ] 관리 페이지의 문제 은행, 시험 관리, 제출 기록 페이지에 접근 가능한지</li><li>[ ] 학생 페이지와 관리 페이지의 스타일이 명확하게 구분되는지</li></ul><h3 id="막혔나요" tabindex="-1">막혔나요? <a class="header-anchor" href="#막혔나요" aria-label="Permalink to “막혔나요?”">​</a></h3><p>프론트엔드 구축 단계에서 막혔다면, 다음 장을 복습하세요:</p><ul><li><a href="./../../backend/database-supabase/">데이터베이스에서 Supabase까지</a></li><li><a href="./../../backend/ai-interface-code/">애플리케이션 백엔드 인터페이스 설계 및 개발</a></li><li><a href="./../../frontend/modern-component-library/">현대적 컴포넌트 라이브러리로 인터페이스 업데이트하기</a></li></ul><h2 id="제3부-백엔드-개발" tabindex="-1">제3부: 백엔드 개발 <a class="header-anchor" href="#제3부-백엔드-개발" aria-label="Permalink to “제3부: 백엔드 개발”">​</a></h2><h3 id="_3-1-로그인-및-권한-제어" tabindex="-1">3.1 로그인 및 권한 제어 <a class="header-anchor" href="#_3-1-로그인-및-권한-제어" aria-label="Permalink to “3.1 로그인 및 권한 제어”">​</a></h3><div class="language-text"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>나를 완전 초보자로 생각하고, 온라인 시험 시스템의 로그인과 권한 제어를 완료해 줘.</span></span>
<span class="line"><span></span></span>
<span class="line"><span>백엔드는 Express를 사용.</span></span>
<span class="line"><span></span></span>
<span class="line"><span>목표:</span></span>
<span class="line"><span>1. 학생과 관리자 모두 로그인 가능</span></span>
<span class="line"><span>2. 로그인 후 사용자 역할 반환</span></span>
<span class="line"><span>3. 학생은 /student/* 관련 인터페이스에만 접근 가능</span></span>
<span class="line"><span>4. 관리자는 /admin/* 관련 인터페이스에만 접근 가능</span></span>
<span class="line"><span>5. 미로그인 사용자가 보호된 페이지에 접근하면 /login으로 이동</span></span>
<span class="line"><span></span></span>
<span class="line"><span>구현 요구사항:</span></span>
<span class="line"><span>- 명확한 디렉토리 구조 제안</span></span>
<span class="line"><span>- 미들웨어가 담당하는 역할을 명확히 설명</span></span>
<span class="line"><span>- 환경 변수가 필요한 부분은 하드코딩하지 마</span></span>
<span class="line"><span>- 완료 후 권한이 정상 작동하는지 확인하는 방법 설명</span></span></code></pre></div><h3 id="_3-2-시험-및-문제-은행-관리-인터페이스" tabindex="-1">3.2 시험 및 문제 은행 관리 인터페이스 <a class="header-anchor" href="#_3-2-시험-및-문제-은행-관리-인터페이스" aria-label="Permalink to “3.2 시험 및 문제 은행 관리 인터페이스”">​</a></h3><p>다음 모듈별로 구현하는 것을 권장합니다:</p><table tabindex="0"><thead><tr><th>모듈</th><th>추천 인터페이스</th></tr></thead><tbody><tr><td>시험 관리</td><td><code>GET /api/exams</code>, <code>POST /api/admin/exams</code>, <code>PATCH /api/admin/exams/:id</code></td></tr><tr><td>문제 은행 관리</td><td><code>GET /api/admin/questions</code>, <code>POST /api/admin/questions</code></td></tr><tr><td>시험 시작</td><td><code>POST /api/submissions/start</code></td></tr><tr><td>시험지 제출</td><td><code>POST /api/submissions/:id/submit</code></td></tr><tr><td>성적 기록</td><td><code>GET /api/student/history</code>, <code>GET /api/admin/submissions</code></td></tr></tbody></table><p>프롬프트 참고:</p><div class="language-text"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>온라인 시험 시스템의 Express API를 설계하고 구현해 줘.</span></span>
<span class="line"><span></span></span>
<span class="line"><span>기능 범위:</span></span>
<span class="line"><span>- 관리자가 시험 생성</span></span>
<span class="line"><span>- 관리자가 문제 은행 유지 관리</span></span>
<span class="line"><span>- 학생이 발행된 시험 확인</span></span>
<span class="line"><span>- 학생이 시험을 시작하고 submission 생성</span></span>
<span class="line"><span>- 학생이 답안을 제출하면 객관식과 참/거짓 문제 자동 채점</span></span>
<span class="line"><span>- 서술형은 먼저 검토 대기로 표시</span></span>
<span class="line"><span>- 학생이 자신의 성적 기록 확인</span></span>
<span class="line"><span>- 관리자가 모든 제출 기록 확인</span></span>
<span class="line"><span></span></span>
<span class="line"><span>요구사항:</span></span>
<span class="line"><span>- 인터페이스 명명이 명확해야 함</span></span>
<span class="line"><span>- 통일된 JSON 구조 반환</span></span>
<span class="line"><span>- 코드에서 controller, service, middleware, db 계층 구분</span></span>
<span class="line"><span>- 각 인터페이스를 테스트하는 방법 설명</span></span></code></pre></div><h3 id="_3-3-채점-로직" tabindex="-1">3.3 채점 로직 <a class="header-anchor" href="#_3-3-채점-로직" aria-label="Permalink to “3.3 채점 로직”">​</a></h3><p>채점 로직은 시험 시스템의 핵심 비즈니스 규칙입니다:</p><ul><li><strong>객관식</strong>: 사용자 답안이 정답과 일치하면 득점</li><li><strong>참/거짓</strong>: 마찬가지로 자동 채점 가능</li><li><strong>서술형</strong>: 첫 번째 버전에서는 답안만 저장하고, 점수는 비워두며, 상태를 <code>reviewed = false</code>로 설정</li></ul><div class="tip custom-block"><p class="custom-block-title">보너스 항목</p><p>AI 기능을 추가하고 싶다면, 관리자가 백엔드에서 &quot;주제 + 난이도&quot;를 입력하면 모델이 먼저 후보 문제를 생성하고, 이를 수동으로 검토하여 문제 은행에 추가할 수 있습니다. 하지만 이것은 보너스 항목이며 필수는 아닙니다.</p></div><h2 id="제4부-통합-디버깅-및-출시" tabindex="-1">제4부: 통합 디버깅 및 출시 <a class="header-anchor" href="#제4부-통합-디버깅-및-출시" aria-label="Permalink to “제4부: 통합 디버깅 및 출시”">​</a></h2><h3 id="_4-1-엔드투엔드-테스트" tabindex="-1">4.1 엔드투엔드 테스트 <a class="header-anchor" href="#_4-1-엔드투엔드-테스트" aria-label="Permalink to “4.1 엔드투엔드 테스트”">​</a></h3><p>최소한 다음 시나리오를 확인하세요:</p><ul><li>학생 로그인 -&gt; 시험 목록 확인 -&gt; 답안 작성 시작 -&gt; 제출 -&gt; 성적 확인</li><li>관리자 로그인 -&gt; 시험 생성 -&gt; 문제 추가 -&gt; 발행 -&gt; 제출 기록 확인</li></ul><h3 id="_4-2-배포" tabindex="-1">4.2 배포 <a class="header-anchor" href="#_4-2-배포" aria-label="Permalink to “4.2 배포”">​</a></h3><ul><li>프론트엔드는 Vercel / Zeabur에 배포</li><li>Express API는 Zeabur / Railway / Render에 배포</li><li>데이터베이스는 Supabase Postgres 또는 호스팅 PostgreSQL 사용</li></ul><p>배포 전 확인:</p><ul><li>[ ] 환경 변수가 완전한지</li><li>[ ] 프론트엔드와 백엔드 API 주소가 올바른지</li><li>[ ] 프로덕션 환경에서 로그인 상태가 정상인지</li><li>[ ] 관리자 계정으로 백엔드에 실제로 접근 가능한지</li><li>[ ] README에 시작, 배포, 테스트 설명이 포함되어 있는지</li></ul><h2 id="산출물" tabindex="-1">산출물 <a class="header-anchor" href="#산출물" aria-label="Permalink to “산출물”">​</a></h2><p>본 프로젝트를 완료한 후, 다음 내용을 제출해야 합니다:</p><ul><li>[ ] 접근 가능한 온라인 데모 링크</li><li>[ ] 소스 코드 저장소 링크 (README 포함)</li><li>[ ] PRD 문서</li><li>[ ] 핵심 페이지 스크린샷 (홈페이지, 학생 시험 목록, 답안 작성 페이지, 관리 백엔드)</li><li>[ ] 60초 데모 영상 (학생 답안 작성 프로세스와 관리자 관리 프로세스 포함)</li></ul><p>README에는 최소한 다음이 포함되어야 합니다: 프로젝트 소개, 핵심 페이지 설명, 기술 스택, 로컬 시작 단계, 환경 변수 목록.</p><h2 id="평가-기준" tabindex="-1">평가 기준 <a class="header-anchor" href="#평가-기준" aria-label="Permalink to “평가 기준”">​</a></h2><table tabindex="0"><thead><tr><th>차원</th><th>기본 요구사항</th><th>심화 요구사항</th></tr></thead><tbody><tr><td>페이지 완성도</td><td>학생 페이지와 관리 페이지의 주요 페이지 모두 접근 가능</td><td>페이지 스타일이 통일되고, 모바일에서 기본적으로 사용 가능</td></tr><tr><td>비즈니스 폐루프</td><td>학생이 로그인, 시험 참여, 제출, 성적 조회 가능</td><td>관리자가 시험을 완전히 생성하고 발행 가능</td></tr><tr><td>데이터 정확성</td><td>답안 제출 후 데이터베이스에 기록되고, 객관식 문제가 자동 채점됨</td><td>서술형 문제에서 수동 검토 또는 AI 보조 지원</td></tr><tr><td>권한 제어</td><td>학생과 관리자의 접근 경계가 명확함</td><td>서버 측 인터페이스에도 역할 검증이 있음</td></tr><tr><td>엔지니어링 납품</td><td>프로젝트가 실행 가능하고, 배포 가능하며, README가 명확함</td><td>데모 영상과 테스트 설명이 있음</td></tr></tbody></table><h2 id="제출-전-확인" tabindex="-1">제출 전 확인 <a class="header-anchor" href="#제출-전-확인" aria-label="Permalink to “제출 전 확인”">​</a></h2>`,51)),l(r,{shadow:"hover",style:{margin:"20px 0","border-radius":"12px"}},{header:t(()=>[...s[0]||(s[0]=[a("div",{style:{"font-weight":"bold","font-size":"16px"}},"제출 전 마지막으로 확인",-1)])]),default:t(()=>[s[1]||(s[1]=a("ul",{style:{"list-style-type":"none","padding-left":"0"}},[a("li",null,[a("label",null,[a("input",{type:"checkbox",disabled:""}),n(" 홈페이지, 로그인 페이지, 학생 페이지, 관리 페이지 모두 완성")])]),a("li",null,[a("label",null,[a("input",{type:"checkbox",disabled:""}),n(" 학생이 정상적으로 시험을 시작하고 답안을 제출할 수 있음")])]),a("li",null,[a("label",null,[a("input",{type:"checkbox",disabled:""}),n(" 관리자가 시험을 생성하고 제출 기록을 확인할 수 있음")])]),a("li",null,[a("label",null,[a("input",{type:"checkbox",disabled:""}),n(" 객관식 문제 점수가 자동으로 계산되어 데이터베이스에 기록됨")])]),a("li",null,[a("label",null,[a("input",{type:"checkbox",disabled:""}),n(" 학생과 관리자 권한 경계가 검증됨")])]),a("li",null,[a("label",null,[a("input",{type:"checkbox",disabled:""}),n(" 프로젝트가 배포되었거나 완전한 로컬 실행 설명이 있음")])])],-1))]),_:1}),s[4]||(s[4]=i('<h2 id="참고-자료" tabindex="-1">참고 자료 <a class="header-anchor" href="#참고-자료" aria-label="Permalink to “참고 자료”">​</a></h2><ul><li><a href="./../../frontend/ui-design/">UI 디자인</a></li><li><a href="./../../frontend/modern-component-library/">현대적 컴포넌트 라이브러리로 인터페이스 업데이트하기</a></li><li><a href="./../../backend/database-supabase/">데이터베이스에서 Supabase까지</a></li><li><a href="./../../backend/ai-interface-code/">대형 언어 모델 활용 인터페이스 코드 및 문서 작성</a></li><li><a href="./../../backend/git-workflow/">Git과 GitHub 워크플로우</a></li><li><a href="./../../backend/zeabur-deployment/">웹 애플리케이션 배포 방법</a></li></ul>',2))])}const y=o(b,[["render",k]]);export{P as __pageData,y as default};
